{"files": [{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "程漫声",
      "role": "protagonist",
      "identity": "烈士遗孤，军事医学研究所研究员（原边境战场战地医疗兵）",
      "traits": ["冷静克制", "直觉敏锐", "柔中带刚", "伤痕下的柔软", "极强的规训意识"],
      "overt_motivation": "完成组织交代的政治联姻任务，不辱使命",
      "covert_motivation": "十年来从未走出边境那场爆炸，想确认眼前这个人是不是他",
      "secret_fear": "如果他真的活着，她所有用来愈合伤口的'他已经死了'将全部崩塌",
      "misperception_of_other": "以为裴征十年前已在边境爆炸中牺牲，现在面前的少将只是一个同名同姓或面容相似的陌生人——直到暗语手势出现",
      "hidden_connection": "十年前在边境战场为裴征做过战场急救缝合，手下的针脚是独一无二的辨识标记"
    },
    {
      "name": "裴征",
      "role": "deuteragonist",
      "identity": "红三代少将，某集团军副参谋长（原边境战场侦察连排长）",
      "traits": ["沉稳威压", "纪律如铁", "细节偏执", "克制到近乎冷酷", "在伤疤处温柔"],
      "overt_motivation": "服从军令完成政治联姻，维护家族与组织的利益",
      "covert_motivation": "他一早就认出了她——十年前为她挡的子弹至今嵌在第三根肋骨旁",
      "secret_fear": "如果她认出他，她会因为那场爆炸的真相恨他——是他的情报失误导致了伏击",
      "misperception_of_other": "以为程漫声在爆炸中双目失明，这些年一直通过隐秘渠道关注'一个盲人女孩'的下落却始终未找到",
      "hidden_connection": "背上枪伤和胸口弹片伤疤都是当年为掩护程漫声撤退时留下的"
    }
  ],
  "supporting_characters": [
    {
      "name": "小季",
      "function": "阻碍",
      "identity": "军区大院哨兵/勤务兵",
      "description": "不直接出场对话，以脚步声、手电光、敲门声存在。每隔15分钟巡逻经过窗下，代表组织无处不在的目光。清晨六点送早餐时敲门，是全文唯一一次直接出声的外部介入。"
    }
  ],
  "relationship_dynamics": "双向隐忍的极端形态：两人都认出了对方，但都认为对方不知道——或者不确定对方是否也认出了自己。裴征多一层秘密（爆炸真相是他的情报失误），程漫声多一层试探本能（她在用身体记忆确认）。军区新房是唯一的封闭舞台，物件（结婚证/军装/手势）是推动关系从伪装到裂缝到共犯的催化剂。核心禁区：承认旧情=承认这场婚姻不是纯粹的政治服从=背叛组织。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕：新房·伪装（约2000字）——建立封闭空间的压迫感，完成两个'陌生人'的第一次独处，通过极度克制的对话和物件展示政治联姻的窒息感，在幕末用战场暗语手势撕开第一道裂缝。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红双喜",
        "core_event": "新婚夜，程漫声独自在贴满红双喜的新房中等待裴征。他进门，两人以陌生夫妻的身份完成第一次独处——敬礼、客套、倒水。每一句话都踩在试探的刀刃上。",
        "emotional_tone": "压抑、克制、暗涌",
        "key_scenes": [
          "开场：结婚证照片NG十遍的闪回（感官触发，<200字）",
          "裴征进门，军装扣子扣到最上面一颗，敬礼式的问候",
          "两人隔着茶几坐，窗外哨兵脚步声第一次经过",
          "她倒水时手指碰到他——他无名指轻叩两下（战场暗语：安全）",
          "两人同时僵住，幕落"
        ]
      }
    ],
    "turning_point": "战场暗语的无意识触发——无名指叩两下'安全'——撕开了伪装的第一道裂缝。这个手势只有十年前边境侦察连的人才知道。"
  },
  "act_two": {
    "description": "第二幕：裂缝·共犯（约4000字）——暗语打开潘多拉之盒，两人在嘴上的官话和手上的暗语之间分裂。监听电话、枪伤暴露与否认、哨兵巡逻间的身体接近，压抑的情欲与不可承认的旧情螺旋缠绕。中点'不要认我'将两人推入共犯关系。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "频率",
        "core_event": "两人开始用手势暗语进行双轨对话（嘴上说官话、手上说心里话）。监听电话响起，两人配合演戏。她发现他背上枪伤是她当年缝合的针脚，他否认说是训练伤。哨兵经过时被迫熄灯靠近，黑暗中她描摹他的伤疤，他在她掌心写'不要认我'。他们在哨兵巡逻间隙中用杀人的手势重新学习温柔。",
        "emotional_tone": "撕裂、灼热、隐痛、禁忌情欲",
        "key_scenes": [
          "手势暗语对话开始：嘴上'首长辛苦了'手上'你还活着'",
          "监听电话响起（勤务处例行问候），两人默契配合演出恩爱夫妻",
          "他脱军装时露出背上枪伤——她认出自己的缝合针脚",
          "他说'训练受的伤'，她说'嗯'，手指在桌下颤抖",
          "哨兵脚步声→熄灯→被迫靠近→黑暗中手指描摹伤疤",
          "他在她掌心用暗语写'不要认我'——中点转折",
          "15分钟巡逻间隙中的身体接触，从克制到失控的边缘",
          "战场手势从暗号变成调情：'掩护我'变成抚摸，'撤退'变成拥抱"
        ]
      }
    ],
    "turning_point": "'不要认我'——这句暗语本身就是矛盾的：只有认出对方的人才需要说'不要认我'。他的否认恰恰是承认。两人从各自隐忍变成了共同的秘密守护者——共犯。"
  },
  "act_three": {
    "description": "第三幕：爆发·新稳态（约2500字）——天将亮，最后的伪装被弹片伤疤撕碎。战场暗语的终极回扣，极限选择后的第三条路，以及封蜡结尾。",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "天亮前",
        "core_event": "她在他胸口发现弹片伤疤（心脏旁），伪装彻底崩裂——'训练的时候，谁会往心脏上打？'他用十年前最后对她说的暗语回答：'撤退，我掩护'。两人面对极限选择，最终选择第三条路：做合格的政治夫妻，在无监听的房间里保留暗语频道。结婚证放入军装内袋贴着伤疤。清晨六点，她开门叫他'裴副参谋长'，他在身后无名指叩两下——安全。",
        "emotional_tone": "崩裂、滚烫、悲壮的温柔、隐忍的重生",
        "key_scenes": [
          "天色将亮，她在他胸口摸到第二个伤疤——弹片，心脏旁",
          "出声崩裂：'训练的时候，谁会往心脏上打？'",
          "他沉默，用手势回答'撤退，我掩护'——十年前最后的话",
          "伪装彻底碎裂，两人短暂的真实对话（极度克制，几乎只有几句）",
